classify:
{
	return switch (c) {
		case "a".code:{
			"a";
		};
		case " ".code | "\t".code | "\n".code:{
			"space";
		};
		case "\\".code:{
			"backslash";
		};
		case _:{
			"other";
		};
	};
}

pair:
{
	return switch (codes) {
		case ["2".code, "1".code]:{
			true;
		};
		case _:{
			false;
		};
	};
}
